import {
  LocalizedPurchaseFlowResponse,
  UpsellProductItem,
  LocalizedVisitorCategoryItem,
  LocalizedEntryVariantItem,
  PurchaseFlowProductMetadataItem,
  PurchaseFlowProductItem,
  PurchaseFlowCalendarItem,
} from "@parksandresorts/webapiproxy-types";

export type TimeLimits = {
  firstEntryTime?: string;
  lastEntryTime?: string;
  firstRideTime?: string;
  lastRideTime?: string;
  rideMinutesFromEntry: number;
  lastActivityRelativeTime: number;
};

export type ProductMetadata = Omit<PurchaseFlowProductMetadataItem, "entryVariant" | "visitorCategory"> & {
  entryVariant?: EntryVariant["id"];
  visitorCategory?: VisitorCategory["id"];
};

export type DateSlot = {
  dateSlotId: number;
  date: string;
  quantity: number;
};

export type Product = Omit<PurchaseFlowProductItem, "productMetadata"> & {
  productMetadata: ProductMetadata;
};

export type CalendarDateResponse = Omit<PurchaseFlowCalendarItem, "products"> & {
  products: Product[];
};

export type VisitorCategory = LocalizedVisitorCategoryItem & {
  id: (typeof VISITOR_CATEGORY)[keyof typeof VISITOR_CATEGORY];
};

export const VISITOR_CATEGORY = {
  ADULT: "Adult",
  CHILD: "Child",
  ELDERLY: "Elderly",
  BABY: "Baby",
} as const;

export type EntryVariant = LocalizedEntryVariantItem & {
  id: (typeof ENTRY_VARIANT)[keyof typeof ENTRY_VARIANT];
};

export const ENTRY_VARIANT = {
  MORNING: "Morning",
  AFTERNOON: "Afternoon",
  DAY: "Day",
  TWO_DAYS: "TwoDays",
  ONE_DAY: "OneDay",
  NIGHT: "Night",
  ADDITIONAL: "Additional",
} as const;

export type UpsellProduct = UpsellProductItem;

export type PurchaseFlowResponse = Omit<
  LocalizedPurchaseFlowResponse,
  "visitorCategories" | "entryVariants" | "calendar"
> & {
  visitorCategories: Record<VisitorCategory["id"], VisitorCategory>;
  entryVariants: Record<EntryVariant["id"], EntryVariant>;
  calendar: Array<CalendarDateResponse>;
};
